// Data labels: what they say, where they stand for every chart type, which
// of the chart type, the series and the point decides, and that labels which
// would lie over each other, leave the frame or cost too much are left out.
// Every chart part is generated by code; text is measured by a stand-in.
//
// Excel is not at hand: what follows its known behaviour without having been
// compared with it is marked UNSURE.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { MAX_DATA_LABELS, chartValues, layoutChart, type ChartItem, type ChartLayout } from '../src/layout/chart';
import type { Chart } from '../src/model/sheet/chart';
import { catAx, chartXml, fakeMeasure, group, numLit, readChart, ser, solid, strLit, valAx, xyAxes, xySer } from './chart-fixtures';

type Of<K extends ChartItem['kind']> = Extract<ChartItem, { kind: K }>;

function model(xml: string): Chart {
  const chart = readChart(xml);
  assert.ok(chart, 'the chart is read');
  return chart as Chart;
}

const lay = (xml: string, width = 480, height = 320): ChartLayout => {
  const chart = model(xml);
  return layoutChart(chart, chartValues(chart), width, height, fakeMeasure);
};
const items = <K extends ChartItem['kind']>(layout: ChartLayout, kind: K, role?: string): Of<K>[] => layout.items.filter((item) => item.kind === kind && (role === undefined || item.role === role)) as Of<K>[];
const labels = (layout: ChartLayout) => items(layout, 'text', 'label');
const near = (actual: number, expected: number, message: string, tolerance = 1e-6) => assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: ${actual} is not ${expected}`);

/** The box a label takes: centred on x, around its line. */
const boxOf = (item: Of<'text'>) => {
  const width = fakeMeasure(item.text, item.font);
  return { left: item.x - width / 2, right: item.x + width / 2, top: item.y - item.font.size * 0.85, bottom: item.y + item.font.size * 0.35 };
};

const CATS = strLit(['Ocak', 'Şubat', 'Mart']);
const show = (flags: string, rest = '') =>
  `<c:dLbls>${rest}${['showLegendKey', 'showVal', 'showCatName', 'showSerName', 'showPercent', 'showBubbleSize'].map((name) => `<c:${name} val="${flags.split(' ').indexOf(name) >= 0 ? 1 : 0}"/>`).join('')}</c:dLbls>`;
const FIXED = valAx('<c:majorGridlines/>', '<c:orientation val="minMax"/><c:max val="40"/><c:min val="-40"/>');
const bars = (series: string, tail = '', head = '<c:barDir val="col"/><c:grouping val="clustered"/>', axes = catAx() + FIXED) => chartXml({ plot: group('barChart', head, series, tail) + axes });
const one = (values: (number | null)[], props = '') => ser(0, { tx: '<c:v>Bir</c:v>', cat: CATS, val: numLit(values), props });

test('labels of columns: the value above each column, in the format of the labels', () => {
  const layout = lay(bars(one([10, 20, 30], show('showVal'))));
  const texts = labels(layout);
  const columns = items(layout, 'rect', 'bar');
  assert.deepEqual(texts.map((item) => item.text), ['10', '20', '30']);
  texts.forEach((item, i) => {
    near(item.x, columns[i].x + columns[i].width / 2, `label ${i} is centred on its column`);
    assert.ok(boxOf(item).bottom <= columns[i].y, `label ${i} stands above its column (${item.y} over ${columns[i].y})`);
    assert.ok(columns[i].y - boxOf(item).bottom < 8, `label ${i} stands close to it`);
    assert.equal(item.align, 'center');
  });
  const formatted = lay(bars(one([10, 20, 30], show('showVal', '<c:numFmt formatCode="0.0" sourceLinked="0"/>'))));
  assert.deepEqual(labels(formatted).map((item) => item.text), ['10.0', '20.0', '30.0']);
  const linked = lay(bars(one([10, 20, 30], show('showVal', '<c:numFmt formatCode="0.0" sourceLinked="1"/>'))));
  assert.deepEqual(labels(linked).map((item) => item.text), ['10', '20', '30'], 'a format that is linked to the cells is that of the series');
  assert.equal(labels(lay(bars(one([10, 20, 30])))).length, 0, 'no labels where none are asked for');
});

test('a negative column has its label below it; a point without a number has none', () => {
  const layout = lay(bars(one([10, -20, null], show('showVal'))));
  const texts = labels(layout);
  const columns = items(layout, 'rect', 'bar');
  assert.deepEqual(texts.map((item) => item.text), ['10', '-20']);
  assert.ok(boxOf(texts[1]).top >= columns[1].y + columns[1].height, 'below the column that hangs');
});

test('where the label of a column stands: outside its end, inside its end, in its middle, inside its base', () => {
  const at = (position: string, head?: string) => {
    const layout = lay(bars(one([10, 20, 30], show('showVal', `<c:dLblPos val="${position}"/>`)), '', head));
    return { label: labels(layout)[2], column: items(layout, 'rect', 'bar')[2] };
  };
  const inEnd = at('inEnd');
  assert.ok(boxOf(inEnd.label).top >= inEnd.column.y && boxOf(inEnd.label).top - inEnd.column.y < 8, 'inEnd: just below the top of the column');
  const centre = at('ctr');
  near((boxOf(centre.label).top + boxOf(centre.label).bottom) / 2, centre.column.y + centre.column.height / 2, 'ctr: in the middle', 0.5);
  const inBase = at('inBase');
  const foot = inBase.column.y + inBase.column.height;
  assert.ok(boxOf(inBase.label).bottom <= foot && foot - boxOf(inBase.label).bottom < 8, 'inBase: just above the foot of the column');
  const outEnd = at('outEnd');
  assert.ok(boxOf(outEnd.label).bottom <= outEnd.column.y, 'outEnd: above');
  const odd = at('r');
  near(odd.label.y, outEnd.label.y, 'a place columns do not have is their own: outside the end');
  const stacked = at('', '<c:barDir val="col"/><c:grouping val="stacked"/>');
  near((boxOf(stacked.label).top + boxOf(stacked.label).bottom) / 2, stacked.column.y + stacked.column.height / 2, 'stacked columns: in the middle by themselves', 0.5);
});

test('bars that lie have their labels beyond their ends, to the right', () => {
  const layout = lay(bars(one([10, 20, 30], show('showVal')), '', '<c:barDir val="bar"/><c:grouping val="clustered"/>'));
  const texts = labels(layout);
  const rects = items(layout, 'rect', 'bar');
  assert.equal(texts.length, 3);
  texts.forEach((item, i) => {
    assert.ok(boxOf(item).left >= rects[i].x + rects[i].width, `label ${i} to the right of its bar`);
    near((boxOf(item).top + boxOf(item).bottom) / 2, rects[i].y + rects[i].height / 2, `label ${i} level with its bar`, 0.5);
  });
});

test('what a label says: the name of the series, the category, the value, with what stands between them', () => {
  const all = lay(bars(one([10, 20, 30], show('showVal showCatName showSerName')), '', undefined, catAx() + FIXED), 900, 400);
  assert.deepEqual(labels(all).map((item) => item.text), ['Bir, Ocak, 10', 'Bir, Şubat, 20', 'Bir, Mart, 30'], 'UNSURE: a comma and a space by default');
  const separated = lay(bars(one([10, 20, 30], show('showVal showCatName', '<c:separator>; </c:separator>'))), 900, 400);
  assert.deepEqual(labels(separated).map((item) => item.text), ['Ocak; 10', 'Şubat; 20', 'Mart; 30']);
  const names = lay(bars(one([10, 20, 30], show('showSerName'))));
  assert.deepEqual(labels(names).map((item) => item.text), ['Bir', 'Bir', 'Bir']);
  const key = lay(bars(one([10, 20, 30], show('showLegendKey'))));
  assert.equal(labels(key).length, 0, 'a legend key alone shows nothing');
});

test('the point decides over the series, the series over the chart type', () => {
  const own =
    '<c:dLbls>' +
    '<c:dLbl><c:idx val="0"/><c:delete val="1"/></c:dLbl>' +
    '<c:dLbl><c:idx val="1"/><c:tx><c:rich><a:bodyPr/><a:p><a:r><a:t>En iyi ay</a:t></a:r></a:p></c:rich></c:tx><c:dLblPos val="ctr"/><c:showVal val="1"/></c:dLbl>' +
    '<c:dLbl><c:idx val="2"/><c:showVal val="0"/><c:showCatName val="1"/></c:dLbl>' +
    '<c:showVal val="1"/></c:dLbls>';
  const layout = lay(bars(one([10, 20, 30], own)));
  const texts = labels(layout);
  assert.deepEqual(texts.map((item) => item.text), ['En iyi ay', 'Mart'], 'none for the first, a text of its own for the second, the category for the third');
  const column = items(layout, 'rect', 'bar')[1];
  near((boxOf(texts[0]).top + boxOf(texts[0]).bottom) / 2, column.y + column.height / 2, 'and the second in the middle of its column', 0.5);

  const two = (props: string) => ser(1, { tx: '<c:v>İki</c:v>', cat: CATS, val: numLit([5, 6, 7]), props });
  const typed = lay(bars(one([10, 20, 30]) + two('<c:dLbls><c:delete val="1"/></c:dLbls>'), show('showVal')));
  assert.deepEqual(labels(typed).map((item) => item.text), ['10', '20', '30'], 'labels of the chart type, but for the series that takes them away');
  const added = lay(bars(one([10, 20, 30], '<c:dLbls><c:dLbl><c:idx val="2"/><c:showVal val="1"/></c:dLbl></c:dLbls>') + two('')));
  assert.deepEqual(labels(added).map((item) => item.text), ['30'], 'a single point may have a label where its series has none');
  const partly = lay(bars(one([10, 20, 30], '<c:dLbls><c:showCatName val="1"/></c:dLbls>'), show('showVal')));
  assert.deepEqual(labels(partly).map((item) => item.text), ['Ocak, 10', 'Şubat, 20', 'Mart, 30'], 'what the series leaves open is what the chart type says');
});

test('the look of labels: size, weight and colour of their text', () => {
  const layout = lay(bars(one([10, 20, 30], show('showVal', `<c:txPr><a:bodyPr/><a:p><a:pPr><a:defRPr sz="1200" b="1">${solid('C00000')}</a:defRPr></a:pPr></a:p></c:txPr>`))));
  const label = labels(layout)[0];
  assert.deepEqual([label.font.size, label.font.bold, label.color], [16, true, '#C00000']);
  const plain = labels(lay(bars(one([10, 20, 30], show('showVal')))))[0];
  assert.deepEqual([plain.font.size, plain.font.bold, plain.color], [12, false, '#595959'], 'nine points in the grey of the chart by default');
});

test('labels of a line stand to the right of their points, or where the file puts them', () => {
  const line = (rest: string) => chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', one([10, 20, 30], show('showVal', rest)), '<c:marker val="1"/>') + catAx() + FIXED });
  const side = (position: string) => {
    const layout = lay(line(position ? `<c:dLblPos val="${position}"/>` : ''));
    const points = items(layout, 'path', 'line')[0].points;
    return { box: boxOf(labels(layout)[1]), x: points[2], y: points[3] };
  };
  const right = side('');
  assert.ok(right.box.left > right.x && right.box.left - right.x < 12, 'to the right by default');
  near((right.box.top + right.box.bottom) / 2, right.y, 'level with the point', 0.5);
  assert.ok(side('l').box.right < side('l').x, 'l: to the left');
  assert.ok(side('t').box.bottom < side('t').y, 't: above');
  assert.ok(side('b').box.top > side('b').y, 'b: below');
  const centre = side('ctr');
  near((centre.box.left + centre.box.right) / 2, centre.x, 'ctr: on the point', 0.5);
  near((centre.box.top + centre.box.bottom) / 2, centre.y, 'ctr: on the point, vertically', 0.5);
});

test('labels of an area stand in the middle of what it covers; labels of a scatter chart say x and y', () => {
  const area = lay(chartXml({ plot: group('areaChart', '<c:grouping val="standard"/>', one([10, 20, 30], show('showVal'))) + catAx() + valAx('', '<c:max val="40"/><c:min val="0"/>') }));
  const texts = labels(area);
  assert.equal(texts.length, 3);
  const foot = area.plot.y + area.plot.height;
  near((boxOf(texts[2]).top + boxOf(texts[2]).bottom) / 2, foot - (30 / 40 / 2) * area.plot.height, 'halfway up the area at the point', 0.5);
  const scatter = lay(chartXml({ plot: group('scatterChart', '<c:scatterStyle val="lineMarker"/>', xySer(0, { tx: '<c:v>Ölçüm</c:v>', cat: numLit([1, 2, 3]), val: numLit([4, 5, 6]), props: show('showVal showCatName') })) + xyAxes() }));
  assert.deepEqual(labels(scatter).map((item) => item.text), ['1, 4', '2, 5', '3, 6'], 'the x value stands for the category');
});

const pie = (values: number[], props: string, name = 'pieChart', tail = '') => chartXml({ plot: group(name, '<c:varyColors val="1"/>', ser(0, { tx: '<c:v>Pay</c:v>', cat: CATS, val: numLit(values), props }), tail, false) });

test('labels of a pie: shares in per cent, inside the slices that have room and outside the ones that have none', () => {
  const layout = lay(pie([1, 2, 3], show('showPercent')));
  const texts = labels(layout);
  assert.deepEqual(texts.map((item) => item.text), ['17%', '33%', '50%']);
  const slices = items(layout, 'slice');
  texts.forEach((item, i) => {
    const slice = slices[i];
    const box = boxOf(item);
    const dx = item.x - slice.cx;
    const dy = (box.top + box.bottom) / 2 - slice.cy;
    const distance = Math.sqrt(dx * dx + dy * dy);
    assert.ok(distance < slice.radius && distance > slice.radius * 0.4, `label ${i} lies inside its slice, towards the rim (${distance} of ${slice.radius})`);
    let angle = Math.atan2(dy, dx);
    while (angle < slice.start) angle += Math.PI * 2;
    assert.ok(angle <= slice.end, `label ${i} lies between the edges of its slice`);
  });
  const outside = lay(pie([1, 2, 3], show('showPercent', '<c:dLblPos val="outEnd"/>')));
  labels(outside).forEach((item, i) => {
    const slice = items(outside, 'slice')[i];
    const box = boxOf(item);
    const dx = item.x - slice.cx;
    const dy = (box.top + box.bottom) / 2 - slice.cy;
    assert.ok(Math.sqrt(dx * dx + dy * dy) > slice.radius, `outEnd: label ${i} lies outside the pie`);
  });
  assert.ok(items(outside, 'slice')[0].radius < items(layout, 'slice')[0].radius, 'a pie with labels outside is smaller, to leave them room');
  // A sliver has no room for a label: bestFit puts it outside.
  const sliver = lay(pie([1, 200, 200], show('showCatName')));
  const first = labels(sliver).filter((item) => item.text === 'Ocak')[0];
  const slice = items(sliver, 'slice')[0];
  assert.ok(first, 'the label of the sliver is shown');
  assert.ok(Math.hypot(first.x - slice.cx, (boxOf(first).top + boxOf(first).bottom) / 2 - slice.cy) > slice.radius, 'outside the pie');
  assert.equal(items(sliver, 'path').length, 0, 'no leader line is drawn');
});

test('labels of a pie: values, categories and shares in a format of their own', () => {
  assert.deepEqual(labels(lay(pie([1, 2, 3], show('showVal showCatName showPercent')), 800, 500)).map((item) => item.text), ['Ocak, 1, 17%', 'Şubat, 2, 33%', 'Mart, 3, 50%']);
  assert.deepEqual(labels(lay(pie([1, 2, 3], show('showPercent', '<c:numFmt formatCode="0.0%" sourceLinked="0"/>')))).map((item) => item.text), ['16.7%', '33.3%', '50.0%']);
  const ring = lay(pie([1, 2, 3], show('showVal'), 'doughnutChart', '<c:holeSize val="50"/>'));
  labels(ring).forEach((item, i) => {
    const slice = items(ring, 'slice')[i];
    const distance = Math.hypot(item.x - slice.cx, (boxOf(item).top + boxOf(item).bottom) / 2 - slice.cy);
    near(distance, (slice.inner + slice.radius) / 2, `the label of slice ${i} of a doughnut lies in the middle of its ring`, 0.5);
  });
});

test('labels that would lie over each other are left out; none leaves the frame', () => {
  const many = Array.from({ length: 60 }, (_value, i) => 1000000 + i);
  const layout = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit(many), props: show('showVal') })) + catAx() + valAx() }));
  const shown = labels(layout);
  assert.ok(shown.length > 3 && shown.length < 60, `${shown.length} of 60 labels are shown`);
  const boxes = shown.map(boxOf);
  for (let a = 0; a < boxes.length; a++) {
    assert.ok(boxes[a].left >= -0.01 && boxes[a].right <= layout.width + 0.01 && boxes[a].top >= -0.01 && boxes[a].bottom <= layout.height + 0.01, `label ${a} lies in the frame`);
    for (let b = a + 1; b < boxes.length; b++) {
      const apart = boxes[a].right <= boxes[b].left || boxes[b].right <= boxes[a].left || boxes[a].bottom <= boxes[b].top || boxes[b].bottom <= boxes[a].top;
      assert.ok(apart, `labels ${a} and ${b} do not overlap`);
    }
  }
  // A label at the top of the scale is moved into the frame rather than cut.
  const tall = lay(bars(one([40, 40, 40], show('showVal')), '', undefined, catAx() + valAx('', '<c:max val="40"/><c:min val="0"/>')), 300, 130);
  for (const item of labels(tall)) assert.ok(boxOf(item).top >= -0.01, 'inside the frame');
});

test('labels are bounded: no more than a chart is worth, none for a series that is sampled, none in a small frame', () => {
  const values = Array.from({ length: 600 }, (_value, i) => i % 7);
  const series = [0, 1, 2].map((index) => ser(index, { val: numLit(values), props: show('showVal') })).join('');
  const chart = model(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', series) + catAx() + valAx() }));
  let measured = 0;
  const counting = (text: string, font: { size: number }) => {
    measured++;
    return fakeMeasure(text, font);
  };
  const bare = model(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', [0, 1, 2].map((index) => ser(index, { val: numLit(values) })).join('')) + catAx() + valAx() }));
  const before = layoutChart(bare, chartValues(bare), 3000, 800, counting);
  const plain = measured;
  measured = 0;
  const layout = layoutChart(chart, chartValues(chart), 3000, 800, counting);
  assert.ok(labels(layout).length <= MAX_DATA_LABELS, `${labels(layout).length} labels`);
  assert.ok(labels(layout).length > 50, 'but many are shown');
  assert.ok(measured - plain <= MAX_DATA_LABELS, `${measured - plain} texts were measured for 1800 points`);
  assert.equal(labels(before).length, 0);
  const sampled = Array.from({ length: 50000 }, (_value, i) => i % 7);
  assert.equal(labels(lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit(sampled), props: show('showVal') })) + catAx() + valAx() }))).length, 0, 'a series that is sampled down has no labels');
  assert.equal(labels(lay(bars(one([10, 20, 30], show('showVal'))), 150, 100)).length, 0, 'a frame too small for words has none');
});

test('labels whatever the numbers: nothing is thrown and every number of the layout is finite', () => {
  const cases: (number | null)[][] = [[1e308, -1e308, 0], [5e-324, 0, null], [], [null, null], [1.7e308, 1.7e308]];
  for (const values of cases) {
    for (const type of ['barChart', 'lineChart', 'areaChart', 'pieChart']) {
      const pieLike = type === 'pieChart';
      const xml = chartXml({ plot: group(type, type === 'barChart' ? '<c:barDir val="col"/>' : '', ser(0, { val: numLit(values), props: show('showVal showCatName showSerName showPercent') }), '', !pieLike) + (pieLike ? '' : catAx() + valAx()) });
      const chart = readChart(xml);
      if (!chart) continue;
      const layout = layoutChart(chart, chartValues(chart), 480, 320, fakeMeasure);
      for (const item of labels(layout)) assert.ok(Number.isFinite(item.x) && Number.isFinite(item.y), `${type} ${JSON.stringify(values)}: a label at ${item.x}, ${item.y}`);
    }
  }
});
